fn is_greater(n: i32, a: &Vec<i32>) -> bool {
    // Since the spec recommends a.len() > 0, we don't need special handling for empty vectors.
    // We check if n is greater than every element in a.
    let mut i = 0;
    while i < a.len() {
        if !(n > a[i]) {
            return false;
        }
        i += 1;
    }
    true
}